const qroc = (enonce, reponse_attendue, sourceBlocks, correction_generale, newInformation = null) => ({ enonce: newInformation ? `${newInformation} ${enonce}` : enonce, format: "qroc", sourceBlocks, reponse_attendue, correction_generale, items: [], ...(newInformation ? { newInformation } : {}) });

